/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Social sign-in ---------- */
.ssi{padding:28px 22px var(--dm-s-5);display:flex;flex-direction:column;align-items:center;gap:14px;max-width:320px;margin:0 auto;width:100%}
.ssi-h{display:flex;flex-direction:column;align-items:center;gap:var(--dm-s-3);text-align:center}
.ssi-lg{width:44px;height:44px;border-radius:calc(14px * var(--dm-rk));background:var(--dm-ink);color:var(--dm-on-ink);display:grid;place-items:center}
.ssi-lg .logo{width:26px;height:26px}
.ssi-h b{font-weight:500;font-size:14px}
.ssi-list{display:flex;flex-direction:column;gap:var(--dm-s-2);width:100%}
.ssi-b{position:relative;display:flex;align-items:center;justify-content:center;gap:10px;height:42px;padding:0 18px;border-radius:var(--dm-r-pill);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);font-size:13.5px;font-weight:500;transition:background .2s,box-shadow .2s,transform .15s}
@media (hover:hover) and (pointer:fine){.ssi-b:hover{background:var(--dm-wash);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-faint) 50%,transparent)}}
.ssi-b:active{transform:scale(.98)}
.ssi-b .mk{width:18px;height:18px;display:grid;place-items:center;flex:none}
.ssi-b .mk svg,.ssi-b .mk img{width:18px;height:18px;display:block}
.ssi-b .mk .i{width:16px;height:16px}
.ssi-b .mk .lt{min-width:18px;height:18px;padding:0 3px;border-radius:5px;background:var(--dm-ink);color:var(--dm-on-ink);display:grid;place-items:center;font-size:10px;font-weight:500}
.ssi-b .last{position:absolute;top:-8px;right:22px;font-size:10.5px;font-weight:500;color:var(--dm-fg2);background:var(--dm-surface);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-rail) 50%,transparent);padding:1px 7px;border-radius:var(--dm-r-pill)}
.ssi-b.last-used{box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-pick-on) 50%,transparent)}
.ssi-b.busy{pointer-events:none}
.ssi-list.wait .ssi-b:not(.busy){opacity:.45}
.ssi-or{display:flex;align-items:center;gap:10px;width:100%;font-size:11.5px;color:var(--dm-muted)}
.ssi-or::before,.ssi-or::after{content:"";flex:1;height:1px;background:var(--dm-line)}
.ssi-mail{font-size:12.5px;color:var(--dm-fg2);padding:var(--dm-s-1) 10px;border-radius:var(--dm-r-pill);transition:color .2s,background .2s}
@media (hover:hover) and (pointer:fine){.ssi-mail:hover{color:var(--dm-fg);background:var(--dm-row)}}
.ssi-ok{display:flex;flex-direction:column;align-items:center;gap:var(--dm-s-2);padding:var(--dm-s-2) 0 var(--dm-s-1);text-align:center;font-size:13px}
.ssi-ok .av{width:44px;height:44px;font-size:14px}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, AV, BRAND, DM, I, hold, html, release, stagger } from '../core/core.js';
DM.def('social-signin', (r, c) => {
  const P = [['Google','google'],['GitHub','github'],['Figma','figma'],['SSO','']];
  let last = 'Figma';
  const list = $('.ssi-list', r), root = $('.ssi', r);
  const mark = p => p[1] ? BRAND[p[1]] : I('lock','s');
  function paint(){
    list.innerHTML = P.map(p => `<button class="ssi-b${p[0] === last ? ' last-used' : ''}" data-p="${p[0]}"><span class="mk">${mark(p)}</span><span class="lb">Continue with ${p[0]}</span>${p[0] === last ? '<span class="last">Last used</span>' : ''}</button>`).join('') + '';
    stagger($$('.ssi-b', list), 50);
    $$('.ssi-b', list).forEach(b => b.onclick = () => c.run(async () => {
      b.classList.add('busy'); list.classList.add('wait'); $('.mk', b).innerHTML = '<span class="spin"></span>';
      await c.wait(1100); last = b.dataset.p;
      hold(root); const kids = [...root.children]; kids.forEach(k => k.hidden = true);
      const ok = html(`<div class="ssi-ok">${AV('MK','var(--dm-av-l)')}<b>Welcome back, Maya</b><span class="muted">Signed in with ${last}</span><button class="pill ghost sm">Sign out</button></div>`);
      root.appendChild(ok); stagger([...ok.children], 60);
      $('button', ok).onclick = () => { ok.remove(); release(root); kids.forEach(k => k.hidden = false); list.classList.remove('wait'); paint(); };
    }));
  }
  paint();
});
